# -*- coding: utf-8 -*-
"""Аптека Хорнета: уличные наркотики, составы для ядов, фармацевтика, дрон, киберимпланты."""
from common import *

ARM = 'ПРАВАЯ КИБЕРРУКА (CYBERARM R)'
INTERNAL = 'ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)'


def build(out):
    P = 'dlc05'
    out.pack(P, 'Аптека Хорнета', "Hornet's Pharmacy")

    def lib(sub):
        e = find(P, sub, 'item')
        return {'Lib': e['id'], 'Page': e['page']}

    G = 'Уличные наркотики'
    out.add(P, 'drug', 'Берсеркер', cost=100, Group=G,
            Info='Действует 10 минут. Критическое повреждение не даёт бонусного урона; штрафы к СТАТам/Действиям от Серьёзного или Смертельного ранения уменьшаются вдвое; штрафы от Запугивания — вдвое. Пользователь очень агрессивен. Вторичный эффект (СЛ17): 2 ПЧ и зависимость — Штраф спасброска постоянно +1, пока не вылечена.', **lib('БЕРСЕРКЕР'))
    out.add(P, 'drug', 'Прайм Тайм', cost=50, Group=G,
            Info='Действует 4 часа. При приёме 4d6 потери Человечности, которые возвращаются после окончания действия (ниже 0 Человечность не падает). ХАР и ВОЛЯ +2 (ПЗ от ВОЛИ не растут). Эмоции подавлены. Вторичный эффект (СЛ17): 1 ПЧ и зависимость — ХАР −2, кроме времени действия препарата.', **lib('ПРАЙМ ТАЙМ'))
    out.add(P, 'drug', 'Шестистволка', cost=100, Group=G,
            Info='Действует 4 часа. СКО и РЕА −2 (минимум 1); +2 к Скорости при Подключении; любое Небезопасное отключение, не вызванное программой, считается Безопасным; раз в ход можно потратить 1 очко ЧЕЛ на 1 дополнительное СЕТевое действие. Вторичный эффект (СЛ17): зависимость — Скорость при Подключении −2, кроме времени действия препарата.')
    out.add(P, 'drug', 'Искривление Времени', cost=100, Group=G,
            Info='Действует 1 минуту: +3 к каждому броску Инициативы; если принят уже в очереди инициативы — текущая инициатива +3. Вторичный эффект (СЛ17): зависимость — −2 ко всем броскам Инициативы, кроме времени действия препарата.', **lib('ИСКРИВЛЕНИЕ'))

    G = 'Составы для ядов'
    out.add(P, 'gear', 'Отсрочивающий состав', cost=50, Group=G,
            Info='Смешивается с флаконом яда или биотоксина действием: действие вещества откладывается на 1 минуту или 1 час после попадания в организм цели.')
    out.add(P, 'gear', 'Дистилляционный состав', cost=100, Group=G,
            Info='Смешивается с флаконом яда или биотоксина действием: СЛ Сопротивления пыткам/наркотикам растёт на 2.')
    out.add(P, 'gear', 'Осмотический состав', cost=50, Group=G,
            Info='Смешивается с флаконом яда или биотоксина действием: вещество проникает через кожу. Наносится на поверхность до 2 м², действует на первое мясное существо, коснувшееся её, держится до 1 часа, смывается водой. Заметить — проверка Внимательности СЛ17.')

    G = 'Новая фармацевтика'
    out.add(P, 'drug', 'Седатив', Group=G,
            Info='Доступно медтехам (Фармацевтика, стр. 149). Согласная цель теряет сознание на 4 часа; лечащий её медтех получает +2 к Хирургии. Сопротивляющаяся цель делает Сопротивление пыткам/наркотикам СЛ15, иначе теряет сознание на 1 минуту (20 раундов) или до получения повреждения/пробуждения.')
    out.add(P, 'drug', 'Истина', Group=G,
            Info='Доступно медтехам. Цель делает Сопротивление пыткам/наркотикам СЛ17, иначе на 10 минут впадает в внушаемое состояние: −5 к проверкам Концентрации, Общения, Дедукции, Проницательности и Убеждения.')

    out.add(P, 'gear', 'Дрон-убийца Судзумебачи', cost=5000, Group='Дроны',
            Info='Летающий насекомовидный дрон размером с книгу в мягкой обложке для тихих убийств. СКО 6, ОС 7, ПЗ 10; взлом — Электроника/Безопасность СЛ17, 5 до взлома. На борту: камера наблюдения (слабое освещение/ИК/УФ), дротикомёт с 8 стрелами с биотоксином, аэрогиппо. Триггер по умолчанию: после того как камера обнаружила лицо по профилю, атакует, пока цель не станет холодной в ИК-диапазоне или не кончатся боеприпасы, затем уходит на дозарядку. Зона: периметр здания (если связан с СЕТью здания) или 50 м от портативной архитектуры СЕТи.', **lib('ДРОН-УБИЙЦА'))

    out.add(P, 'cyber', 'Автоинъектор Бодивейт', cost=100, Install='Клиника', HL='3 (1d6)', Category=INTERNAL, Slots=1,
            Info='Внутренний киберимплант. Действием вводится одна доза уличного наркотика в подкожный резервуар; затем действием препарат вводится в тело. С Биомонитором можно запрограммировать автоинъекцию при броске Инициативы, критической травме или определённом состоянии ранения.')
    out.add(P, 'cyber', 'Газомёт Стремительной Охраны ИНК.', cost=500, Install='Клиника', HL='7 (2d6)', Category=ARM, Slots=2,
            Info='Модуль киберруки, 2 слота. Аэрозольный газомёт на 3 дозы уличного наркотика или 3 ампулы яда/биотоксина; прячется без проверки. Работает как одноручный экзотический дробовик с одним зарядом, только «Выстрел дробью»: вместо урона вызывает эффект вещества у поражённой цели. Каждый выстрел требует полной зарядки.')
